import React, { useEffect, useMemo, useState } from 'react';
import {
  Box,
  CircularProgress,
  Divider,
  Grid,
  Stack,
  Typography,
  useMediaQuery,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
} from '@mui/material';
import ReceiptLongOutlinedIcon from '@mui/icons-material/ReceiptLongOutlined';
import { theme } from '../../../theme';
import { IUserInfo } from '../../../core/Interface/user.interface';
import {
  formatDateTime,
  getPriceFormat,
  getPriceFormatWithoutCurrency,
} from '../../../core/utils';
import {
  useGetPurchaseDetailsByOrderIdQuery,
  useGetUserQuery,
} from '../../posApi';
// eslint-disable-next-line import/no-extraneous-dependencies
import * as XLSX from 'xlsx';
import { appColors, HEADER_GRADIENT } from '../../../theme/appColors';
import FileDownloadIcon from '@mui/icons-material/FileDownload';
import { Privileges } from '../../../core/types/commonType';
import { IPurchaseReceipt } from '../../../core/Interface/purchase.interface';

interface INewReceipt {
  openModel: boolean;
  handleCloseDialog: () => void;
  purchaseId: string;
}

const NewReceipt = ({
  openModel,
  handleCloseDialog,
  purchaseId,
}: INewReceipt) => {
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const [purchaseDetails, setPurchaseDetails] = useState<IPurchaseReceipt>();

  const { data, isLoading, isFetching } = useGetPurchaseDetailsByOrderIdQuery(
    purchaseId.split('_')[0],
    { skip: !purchaseId }
  );

  const { data: companyData } = useGetUserQuery();

  const hasDownloadPermission = companyData?.data
    ? (companyData.data as IUserInfo).privileges.includes(
        Privileges.Download_Excel_PurchaseDetails
      )
    : false;

  const currencyCode = useMemo(() => {
    if (companyData?.data) {
      const userData = companyData.data as IUserInfo;
      if (userData.company.currencyCode) {
        return userData.company.currencyCode;
      }
    }
    return '';
  }, [companyData]);

  useEffect(() => {
    if (data) {
      setPurchaseDetails(data.data as IPurchaseReceipt);
    }
  }, [data]);

  const PurchaseReceiptDataMemo = useMemo(
    () => purchaseDetails,
    [purchaseDetails]
  );
  const isJewellery = PurchaseReceiptDataMemo?.isJewellery === true;

  const downloadExcel = (purchase: IPurchaseReceipt) => {
    const wsData = [];

    // HEADER
    wsData.push([purchase.headerText1]);
    wsData.push([purchase.headerText2]);
    wsData.push([purchase.headerText3]);
    wsData.push([`Mobile: ${purchase.mobile}`]);
    wsData.push([purchase.email]);
    wsData.push([]);

    // SALES & RECEIPT & DATE
    wsData.push([`Purchase By: ${purchase.purchaseBy}`]);

    const formattedDate = new Date(purchase.dateTime).toLocaleString('en-GB');
    wsData.push([
      `Receipt ${purchase.receiptNo}`,
      '',
      '',
      '',
      '',
      `Date: ${formattedDate}`,
    ]);

    wsData.push([]);
    wsData.push([]);

    // TABLE HEADER
    if (purchase.isJewellery) {
      wsData.push([
        'Qty',
        'Description',
        'Gold Karat',
        'Gold Weight',
        'Cost',
        'Amount',
      ]);
    } else {
      wsData.push([
        'Qty',
        'F.Qty',
        'T.Qty',
        'Description',
        'Unit Price',
        'Cost/Item',
        'Discount/Item',
        'Discount Value',
        'T.Discount',
        'Selling Price',
        'Amount',
      ]);
    }

    //  ITEMS
    purchase.items.forEach((item) => {
      if (purchase.isJewellery) {
        wsData.push([
          item.qty,
          item.productName,
          item.goldKarat ?? '-',
          item.goldWeight ?? '-',
          getPriceFormat(item.cost, currencyCode),
          getPriceFormat(item.totalAmount, currencyCode),
        ]);
      } else {
        wsData.push([
          item.qty,
          item.freeQty,
          item.totalQty,
          item.productName,
          getPriceFormat(item.unitPrice, currencyCode),
          getPriceFormat(item.cost, currencyCode),
          getPriceFormat(item.discountAmount, currencyCode),
          item.isPercentage
            ? `${item.discountValue}%`
            : getPriceFormat(item.discountValue, currencyCode),
          getPriceFormat(item.totalDiscountAmount, currencyCode),
          getPriceFormat(item.sellingPrice, currencyCode),
          getPriceFormat(item.totalAmount, currencyCode),
        ]);
      }
    });

    wsData.push([]);
    wsData.push([]);

    //

    if (purchase.isJewellery) {
      wsData.push([
        '',
        '',
        '',
        '',
        'SubTotal',
        getPriceFormat(purchase.subTotal, currencyCode),
      ]);
      wsData.push([
        '',
        '',
        '',
        '',
        'Net Total',
        getPriceFormat(purchase.netTotal, currencyCode),
      ]);
    } else {
      wsData.push([
        '',
        '',
        '',
        '',
        '',
        '',
        '',
        '',
        '',
        'SubTotal',
        getPriceFormat(purchase.subTotal, currencyCode),
      ]);
      wsData.push([
        '',
        '',
        '',
        '',
        '',
        '',
        '',
        '',
        '',
        `Discount Amount [${purchase.isPercentage
          ? `${purchase.discountValue}%`
          : getPriceFormatWithoutCurrency(purchase.discountValue)}]`,
        getPriceFormat(purchase.totalDiscountAmount, currencyCode),
      ]);
      wsData.push([
        '',
        '',
        '',
        '',
        '',
        '',
        '',
        '',
        '',
        'Net Total',
        getPriceFormat(purchase.netTotal, currencyCode),
      ]);
    }

    // sheet
    const ws = XLSX.utils.aoa_to_sheet(wsData);

    ws['!cols'] = purchase.isJewellery
      ? [
          { wch: 8 },
          { wch: 22 },
          { wch: 14 },
          { wch: 14 },
          { wch: 12 },
          { wch: 14 },
        ]
      : [
          { wch: 8 },
          { wch: 8 },
          { wch: 8 },
          { wch: 22 },
          { wch: 12 },
          { wch: 12 },
          { wch: 12 },
          { wch: 14 },
          { wch: 12 },
          { wch: 14 },
          { wch: 12 },
        ];
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Purchase Details');

    XLSX.writeFile(wb, 'purchase_details.xlsx');
  };

  return (
    <Dialog
      aria-describedby="alert-dialog-description"
      fullScreen={isMobile}
      fullWidth={!isMobile}
      maxWidth="lg"
      onClose={handleCloseDialog}
      open={openModel}
      PaperProps={{ sx: { borderRadius: isMobile ? 0 : '12px', overflow: 'hidden' } }}
    >
      <DialogTitle sx={{ p: 0 }}>
        <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2 }}>
          <Stack alignItems="center" direction="row" spacing={1.5}>
            <Box sx={{ alignItems: 'center', background: 'rgba(255,255,255,0.15)', borderRadius: '8px', display: 'flex', height: 36, justifyContent: 'center', width: 36, flexShrink: 0 }}>
              <ReceiptLongOutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
            </Box>
            <Box>
              <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>Purchase Details</Typography>
              <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>Purchase receipt details</Typography>
            </Box>
          </Stack>
        </Box>
      </DialogTitle>
      <DialogContent
        sx={{
          px: 3,
          pt: 3,
          pb: 1,
        }}
      >
        {isLoading || isFetching ? (
          <Box
            sx={{
              display: 'flex',
              justifyContent: 'center',
              alignItems: 'center',
              width: '100%',
              height: '100%',
              mt: 4,
            }}
          >
            <CircularProgress />
          </Box>
        ) : (
          <Box
            sx={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
            }}
          >
            {PurchaseReceiptDataMemo ? (
              <>
                <Grid
                  container
                  spacing={2}
                >
                  <Grid
                    item
                    xs={12}
                  >
                    <Box sx={{ mt: '15px', mb: '15px' }}>
                      <div
                        style={{
                          display: 'flex',
                          flexDirection: 'row',
                          gap: '4px',
                          textAlign: 'left',
                        }}
                      >
                        <div
                          style={{
                            flex: '0 0 auto',
                            display: 'flex',
                            flexDirection: 'column',
                            alignItems: 'flex-start',
                            marginRight: '4px',
                          }}
                        >
                          <Typography sx={{ fontWeight: 'bold' }}>
                            Purchase By
                          </Typography>
                          <Typography sx={{ fontWeight: 'bold' }}>
                            Receipt No
                          </Typography>
                        </div>

                        <div
                          style={{
                            flex: '0 0 auto',
                            display: 'flex',
                            flexDirection: 'column',
                            alignItems: 'flex-end',
                            marginRight: '4px',
                          }}
                        >
                          <Typography sx={{ fontWeight: 'bold' }}>:</Typography>
                          <Typography sx={{ fontWeight: 'bold' }}>:</Typography>
                        </div>

                        <div
                          style={{
                            flex: '1',
                            display: 'flex',
                            flexDirection: 'column',
                            gap: '0px',
                          }}
                        >
                          <Typography variant="body1">
                            {PurchaseReceiptDataMemo.purchaseBy}
                          </Typography>
                          <Typography variant="body1">
                            {PurchaseReceiptDataMemo.receiptNo}
                          </Typography>
                        </div>

                        <div
                          style={{
                            flex: '0 0 auto',
                            display: 'flex',

                            alignItems: 'flex-end',
                          }}
                        >
                          {' '}
                          <div
                            style={{
                              flex: '0 0 auto',
                              display: 'flex',
                              flexDirection: 'column',
                              alignItems: 'flex-start',
                              marginRight: '4px',
                            }}
                          >
                            <Typography sx={{ fontWeight: 'bold' }}>
                              Date
                            </Typography>
                            <Typography sx={{ fontWeight: 'bold' }}>
                              Mobile
                            </Typography>
                          </div>
                          <div
                            style={{
                              flex: '0 0 auto',
                              display: 'flex',
                              flexDirection: 'column',
                              alignItems: 'flex-end',
                              marginLeft: '4px',
                              marginRight: '6px',
                            }}
                          >
                            <Typography sx={{ fontWeight: 'bold' }}>
                              :
                            </Typography>
                            <Typography sx={{ fontWeight: 'bold' }}>
                              :
                            </Typography>
                          </div>
                          <div
                            style={{
                              flex: '1',
                              display: 'flex',
                              alignItems: 'flex-start',
                              flexDirection: 'column',
                              gap: '0px',
                            }}
                          >
                            <Typography variant="body1">
                              {formatDateTime(
                                new Date(PurchaseReceiptDataMemo.dateTime)
                              )}
                            </Typography>
                            <Typography variant="body1">
                              {PurchaseReceiptDataMemo.supplierNameOrMobile}
                            </Typography>
                          </div>
                        </div>
                      </div>
                    </Box>
                  </Grid>
                </Grid>{' '}
                <Divider
                  flexItem
                  orientation="horizontal"
                />
                <Grid
                  container
                  my={2}
                  spacing={2}
                >
                  <TableContainer>
                    <Table>
                      <TableHead>
                        <TableRow>
                          <TableCell sx={{ fontSize: 18 }}>Qty</TableCell>

                          {!isJewellery && (
                            <TableCell sx={{ fontSize: 18 }}>F.Qty</TableCell>
                          )}
                          {!isJewellery && (
                            <TableCell sx={{ fontSize: 18 }}>T.Qty</TableCell>
                          )}
                          <TableCell sx={{ fontSize: 18 }}>
                            Description
                          </TableCell>
                          <TableCell
                            align={isJewellery ? 'left' : 'right'}
                            sx={{ fontSize: 18 }}
                          >
                            Unit Price
                          </TableCell>

                          {isJewellery ? (
                            <>
                              <TableCell sx={{ fontSize: 18 }}>
                                Gold Karat
                              </TableCell>
                              <TableCell sx={{ fontSize: 18 }}>
                                Gold Weight
                              </TableCell>

                              <TableCell
                                align="right"
                                sx={{ fontSize: 18 }}
                              >
                                Cost
                              </TableCell>
                            </>
                          ) : (
                            <>
                              <TableCell
                                align="right"
                                sx={{ fontSize: 18 }}
                              >
                                Cost/Item
                              </TableCell>
                              <TableCell
                                align="right"
                                sx={{ fontSize: 18 }}
                              >
                                Discount/Item
                              </TableCell>
                              <TableCell
                                align="right"
                                sx={{ fontSize: 18 }}
                              >
                                Discount Value
                              </TableCell>
                              <TableCell
                                align="right"
                                sx={{ fontSize: 18 }}
                              >
                                T.Discount
                              </TableCell>
                              <TableCell
                                align="right"
                                sx={{ fontSize: 18 }}
                              >
                                Selling Price
                              </TableCell>
                            </>
                          )}

                          <TableCell
                            align="right"
                            sx={{ fontSize: 18 }}
                          >
                            Amount
                          </TableCell>
                        </TableRow>
                      </TableHead>

                      <TableBody>
                        {PurchaseReceiptDataMemo &&
                          PurchaseReceiptDataMemo.items &&
                          PurchaseReceiptDataMemo.items.map((item, index) => (
                            <TableRow key={index}>
                              <TableCell>{item.qty}</TableCell>

                              {!isJewellery && (
                                <TableCell>{item.freeQty}</TableCell>
                              )}
                              {!isJewellery && (
                                <TableCell>{item.totalQty}</TableCell>
                              )}
                              <TableCell>{item.productName}</TableCell>
                              <TableCell align={isJewellery ? 'left' : 'right'}>
                                {getPriceFormat(item.unitPrice, currencyCode)}
                              </TableCell>
                              {isJewellery ? (
                                <>
                                  <TableCell>{item.goldKarat ?? '-'}</TableCell>
                                  <TableCell>
                                    {item.goldWeight ?? '-'}
                                  </TableCell>
                                  <TableCell align="right">
                                    {getPriceFormat(item.cost, currencyCode)}
                                  </TableCell>
                                </>
                              ) : (
                                <>
                                  <TableCell align="right">
                                    {getPriceFormat(item.cost, currencyCode)}
                                  </TableCell>
                                  <TableCell align="right">
                                    {getPriceFormat(
                                      item.discountAmount,
                                      currencyCode
                                    )}
                                  </TableCell>
                                  <TableCell align="right">
                                    {item.isPercentage
                                      ? `${item.discountValue}%`
                                      : getPriceFormat(
                                          item.discountValue,
                                          currencyCode
                                        )}
                                  </TableCell>

                                  <TableCell align="right">
                                    {getPriceFormat(
                                      item.totalDiscountAmount,
                                      currencyCode
                                    )}
                                  </TableCell>
                                  <TableCell align="right">
                                    {getPriceFormat(
                                      item.sellingPrice,
                                      currencyCode
                                    )}
                                  </TableCell>
                                </>
                              )}

                              <TableCell align="right">
                                {getPriceFormat(item.totalAmount, currencyCode)}
                              </TableCell>
                            </TableRow>
                          ))}
                      </TableBody>
                    </Table>
                  </TableContainer>
                </Grid>
                <Divider
                  flexItem
                  orientation="horizontal"
                />
                <Grid
                  container
                  spacing={2}
                >
                  <Grid
                    item
                    xs={6}
                  >
                    <Box sx={{ mt: '10px', mb: '10px' }}>
                      <Typography fontSize={18}>SubTotal</Typography>
                    </Box>
                  </Grid>
                  <Grid
                    item
                    xs={6}
                  >
                    <Box sx={{ mt: '10px', mb: '10px', textAlign: 'right' }}>
                      <Typography
                        fontSize={18}
                        sx={{ mr: 1 }}
                      >
                        {getPriceFormat(
                          PurchaseReceiptDataMemo.subTotal,
                          currencyCode
                        )}
                      </Typography>
                    </Box>
                  </Grid>
                </Grid>
                {!isJewellery && (
                  <Grid
                    container
                    spacing={2}
                  >
                    <Grid
                      item
                      xs={6}
                    >
                      <Box sx={{ mt: '10px', mb: '10px' }}>
                        <Typography fontSize={18}>
                          Discount Amount
                          {PurchaseReceiptDataMemo.isPercentage
                            ? ` [ ${PurchaseReceiptDataMemo.discountValue}% ]`
                            : ` [ ${getPriceFormatWithoutCurrency(
                                PurchaseReceiptDataMemo.discountValue
                              )} ]`}
                        </Typography>
                      </Box>
                    </Grid>
                    <Grid
                      item
                      xs={6}
                    >
                      <Box sx={{ mt: '10px', mb: '10px', textAlign: 'right' }}>
                        <Typography
                          fontSize={18}
                          sx={{ mr: 1 }}
                        >
                          {getPriceFormat(
                            PurchaseReceiptDataMemo.totalDiscountAmount,
                            currencyCode
                          )}
                        </Typography>
                      </Box>
                    </Grid>
                  </Grid>
                )}
                <Grid
                  container
                  spacing={2}
                >
                  <Grid
                    item
                    xs={6}
                  >
                    <Box sx={{ mt: '10px', mb: '10px' }}>
                      <Typography fontSize={18}>Net Total</Typography>
                    </Box>
                  </Grid>
                  <Grid
                    item
                    xs={6}
                  >
                    <Box sx={{ mt: '10px', mb: '10px', textAlign: 'right' }}>
                      <Typography
                        fontSize={18}
                        sx={{ mr: 1 }}
                      >
                        {getPriceFormat(PurchaseReceiptDataMemo.netTotal)}
                      </Typography>
                    </Box>
                  </Grid>
                </Grid>
                <Divider
                  flexItem
                  orientation="horizontal"
                />
              </>
            ) : (
              <Typography variant="body1">No data available</Typography>
            )}
            <Divider
              flexItem
              orientation="horizontal"
            />
          </Box>
        )}
      </DialogContent>
      <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
        {hasDownloadPermission && (
          <Button
            color="primary"
            disabled={isFetching || !PurchaseReceiptDataMemo}
            onClick={() =>
              PurchaseReceiptDataMemo && downloadExcel(PurchaseReceiptDataMemo)
            }
            sx={{
              border: 'none',
              width: 150,
              height: 42,
              borderRadius: '8px',
              fontWeight: 'bold',
              backgroundColor: appColors.darkGreen[20],
              cursor: 'pointer',
              '&:hover': { backgroundColor: appColors.greyishBlue[20] },
            }}
            variant="outlined"
          >
            <FileDownloadIcon />
            Download
          </Button>
        )}

        <Button
          color="primary"
          onClick={handleCloseDialog}
          sx={{ borderColor: '#CBD5E1', borderRadius: '8px', color: '#475569', fontWeight: 600, height: 40, minWidth: 110, px: 3, textTransform: 'none', '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' } }}
          variant="outlined"
        >
          Cancel
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default React.memo(NewReceipt);
