import React from 'react';
import { IPurchaseListData } from '../../core/Interface/purchase.interface';
import { ColumnDef } from '@tanstack/react-table';
import { formatDateTime, getPriceFormat } from '../../core/utils';
import { Box, Tooltip } from '@mui/material';
import VisibilityIcon from '@mui/icons-material/Visibility';
import { useTranslation } from 'react-i18next';
import { appColors } from '../../theme/appColors';
import FormatListBulletedIcon from '@mui/icons-material/FormatListBulleted';

const usePurchaseListColumn = ({
  viewPurchaseDetails,
  viewPurchaseDetailsPopUp,
  currencyCode,
}: {
  viewPurchaseDetails?: (id: string) => void;
  viewPurchaseDetailsPopUp?: (id: string) => void;
  currencyCode: string;
}) => {
  const { t } = useTranslation(['purchaseList']);

  return [
    {
      accessorKey: 'sn',
      header: <div style={{ textAlign: 'justify' }}>#</div>,
      size: 50,
    },
    {
      accessorKey: 'receiptNo',
      header: t('purchaseList:receiptID'),
      size: 180,
    },
    {
      accessorKey: 'supplierNameOrMobile',
      header: t('purchaseList:supplierName'),
      size: 180,
    },
    {
      accessorKey: 'netTotal',
      header: () => (
        <Box sx={{ textAlign: 'right' }}>{t('purchaseList:total')}</Box>
      ),
      size: 200,
      cell: (cell) => {
        return (
          <Box sx={{ textAlign: 'right' }}>
            {getPriceFormat(cell.row.original.netTotal, currencyCode)}
          </Box>
        );
      },
    },
    {
      accessorKey: 'dateTime',
      header: () => (
        <Box sx={{ textAlign: 'right' }}>{t('purchaseList:date')}</Box>
      ),
      size: 180,
      cell: (cell) => {
        return (
          <Box sx={{ textAlign: 'right' }}>
            {formatDateTime(new Date(cell.row.original.dateTime))}
          </Box>
        );
      },
    },
    {
      id: 'actions',
      header: '',
      size: 20,
      cell: (cell) => {
        const row = cell.row;
        const data = row.original;

        const ActionButton = ({
          onClick,
          title,
          bgColor,
          hoverColor,
          children,
        }: {
          onClick: () => void;
          title: string;
          bgColor: string;
          hoverColor: string;
          children: React.ReactNode;
        }) => {
          return (
            <Tooltip
              arrow
              title={title}
            >
              <Box
                onClick={(e) => {
                  e.stopPropagation();
                  onClick();
                }}
                sx={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  width: 30,
                  height: 30,
                  borderRadius: '50%',
                  backgroundColor: bgColor,
                  cursor: 'pointer',
                  transition: 'all 0.2s ease',
                  '&:hover': {
                    backgroundColor: hoverColor,
                    transform: 'scale(1.08)',
                  },
                }}
              >
                {children}
              </Box>
            </Tooltip>
          );
        };

        return (
          <Box
            sx={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'flex-end',
              gap: 1,
              width: '100%',
            }}
          >
            {/* View Receipt */}
            <ActionButton
              bgColor={appColors.greenSmoke[60]}
              hoverColor={appColors.greenSmoke[100]}
              onClick={() => viewPurchaseDetails?.(data.id)}
              title="View Receipt"
            >
              <VisibilityIcon
                fontSize="small"
                sx={{ color: appColors.white }}
              />
            </ActionButton>

            {/* View Popup */}
            <ActionButton
              bgColor={appColors.persianBlue[60]}
              hoverColor={appColors.persianBlue[100]}
              onClick={() => viewPurchaseDetailsPopUp?.(data.id)}
              title="View Details Popup"
            >
              <FormatListBulletedIcon
                fontSize="small"
                sx={{ color: appColors.white }}
              />
            </ActionButton>
          </Box>
        );
      },
    },
  ] as ColumnDef<IPurchaseListData>[];
};

export default usePurchaseListColumn;
