/* eslint-disable react/display-name */
import React, { useMemo } from 'react';
import {
  Box,
  CardMedia,
  Divider,
  Grid,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import { IPurchaseReceipt } from '../../../core/Interface/purchase.interface';
import { formatDateTime, getPriceFormat } from '../../../core/utils';

export const Receipt = React.forwardRef<
  HTMLDivElement,
  { purchaseRes: IPurchaseReceipt; currencyCode: string }
>(({ purchaseRes, currencyCode }, ref) => {
  const PurchaseReceiptDataMemo = useMemo(() => {
    return purchaseRes;
  }, [purchaseRes]);
  const isJewellery = PurchaseReceiptDataMemo?.isJewellery === true;

  return (
    <div
      ref={ref}
      style={{ paddingLeft: '45px', paddingRight: '45px' }}
    >
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
        }}
      >
        <Box
          sx={{
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justify: 'center',
          }}
        >
          <CardMedia
            alt="logo"
            component="img"
            image={PurchaseReceiptDataMemo.logo}
            sx={{
              height: '80px',
              width: '80px',
              p: 0,
              m: 0,
            }}
          />
          <Typography
            align="center"
            fontSize={17}
            sx={{ fontWeight: 600 }}
          >
            {PurchaseReceiptDataMemo.headerText1}
          </Typography>
          <Typography
            align="center"
            fontSize={17}
            sx={{ fontWeight: 600 }}
          >
            {PurchaseReceiptDataMemo.headerText2}
          </Typography>
          <Typography
            align="center"
            fontSize={17}
            sx={{ fontWeight: 600 }}
          >
            {PurchaseReceiptDataMemo.headerText3}
          </Typography>
          <Typography
            align="center"
            fontSize={17}
            sx={{ fontWeight: 600 }}
          >
            {PurchaseReceiptDataMemo.email}
          </Typography>
          <Typography
            align="center"
            fontSize={17}
            sx={{ fontWeight: 600 }}
          >
            {PurchaseReceiptDataMemo.mobile}
          </Typography>
        </Box>
        <Box sx={{ height: '20px' }} />
        <Divider
          flexItem
          orientation="horizontal"
        />
        <Grid
          container
          spacing={2}
        >
          <Grid
            item
            xs={6}
          >
            <Box sx={{ mt: '15px', mb: '15px' }}>
              <Typography variant="body1">
                Purchase By: {PurchaseReceiptDataMemo.purchaseBy}
              </Typography>
              <Typography variant="body1">
                Receipt ID: {PurchaseReceiptDataMemo.receiptNo}
              </Typography>
            </Box>
          </Grid>
          <Grid
            item
            xs={6}
          >
            <Box sx={{ mt: '15px', mb: '15px', textAlign: 'right' }}>
              <Typography variant="body1">
                Date:{' '}
                {formatDateTime(new Date(PurchaseReceiptDataMemo.dateTime))}
              </Typography>
              <Typography variant="body1">
                Mobile: {PurchaseReceiptDataMemo.mobile}
              </Typography>
            </Box>
          </Grid>
        </Grid>
        <Divider
          flexItem
          orientation="horizontal"
        />
      </Box>
      <TableContainer>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell
                align="left"
                sx={{
                  fontSize: 20,
                }}
              >
                Qty
              </TableCell>
              <TableCell
                sx={{
                  fontSize: 20,
                }}
              >
                Description
              </TableCell>

              {isJewellery && (
                <TableCell
                  align="right"
                  sx={{ fontSize: 20 }}
                >
                  Gold Weight (g)
                </TableCell>
              )}
              {isJewellery && (
                <TableCell
                  align="right"
                  sx={{
                    fontSize: 20,
                  }}
                >
                  Unit Price (8g)
                </TableCell>
              )}
              {!isJewellery && (
                <TableCell
                  align="right"
                  sx={{
                    fontSize: 20,
                  }}
                >
                  Cost
                </TableCell>
              )}
              {!isJewellery && (
                <TableCell
                  align="right"
                  sx={{ fontSize: 20 }}
                >
                  Selling Price
                </TableCell>
              )}

              <TableCell
                align="right"
                sx={{
                  fontSize: 20,
                }}
              >
                Amount
              </TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {PurchaseReceiptDataMemo &&
              PurchaseReceiptDataMemo.items &&
              PurchaseReceiptDataMemo.items.map((item, index) => (
                <TableRow key={index}>
                  <TableCell
                    align="left"
                    sx={{
                      typography: 'body1',
                      borderBottom: 'none',
                    }}
                  >
                    {item.totalQty}
                  </TableCell>
                  <TableCell
                    sx={{
                      maxWidth: 100,
                      wordWrap: 'break-word',
                      typography: 'body1',
                      borderBottom: 'none',
                    }}
                  >
                    {item.productName}
                  </TableCell>
                  {isJewellery && (
                    <TableCell
                      align="right"
                      sx={{ typography: 'body1', borderBottom: 'none' }}
                    >
                      {item.goldWeight ?? '-'}
                    </TableCell>
                  )}
                  {isJewellery && (
                    <TableCell
                      align="right"
                      sx={{
                        typography: 'body1',
                        borderBottom: 'none',
                      }}
                    >
                      {getPriceFormat(item.unitPrice, currencyCode)}
                    </TableCell>
                  )}
                  {!isJewellery && (
                    <TableCell
                      align="right"
                      sx={{
                        typography: 'body1',
                        borderBottom: 'none',
                      }}
                    >
                      {getPriceFormat(item.cost, currencyCode)}
                    </TableCell>
                  )}
                  {!isJewellery && (
                    <TableCell
                      align="right"
                      sx={{
                        typography: 'body1',
                        borderBottom: 'none',
                      }}
                    >
                      {getPriceFormat(item.sellingPrice, currencyCode)}
                    </TableCell>
                  )}
                  <TableCell
                    align="right"
                    sx={{
                      typography: 'body1',
                      borderBottom: 'none',
                    }}
                  >
                    {getPriceFormat(item.totalAmount, currencyCode)}
                  </TableCell>
                </TableRow>
              ))}
          </TableBody>
        </Table>
      </TableContainer>
      <Divider
        flexItem
        orientation="horizontal"
      />
      <Grid
        container
        spacing={2}
      >
        <Grid
          item
          xs={6}
        >
          <Box sx={{ mt: '10px', mb: '10px' }}>
            <Typography fontSize={20}>SubTotal</Typography>
          </Box>
        </Grid>
        <Grid
          item
          xs={6}
        >
          <Box sx={{ mt: '10px', mb: '10px', textAlign: 'right' }}>
            <Typography fontSize={20}>
              {getPriceFormat(PurchaseReceiptDataMemo.subTotal, currencyCode)}
            </Typography>
          </Box>
        </Grid>
      </Grid>
      {!isJewellery && (
        <Grid
          container
          spacing={2}
        >
          <Grid
            item
            xs={6}
          >
            <Box sx={{ mt: '10px', mb: '10px' }}>
              <Typography fontSize={20}>Discount Amount</Typography>
            </Box>
          </Grid>
          <Grid
            item
            xs={6}
          >
            <Box sx={{ mt: '10px', mb: '10px', textAlign: 'right' }}>
              <Typography fontSize={20}>
                {getPriceFormat(
                  PurchaseReceiptDataMemo.totalDiscountAmount,
                  currencyCode
                )}
              </Typography>
            </Box>
          </Grid>
        </Grid>
      )}
      <Grid
        container
        spacing={2}
      >
        <Grid
          item
          xs={6}
        >
          <Box sx={{ mt: '10px', mb: '10px' }}>
            <Typography fontSize={20}>Net Total</Typography>
          </Box>
        </Grid>
        <Grid
          item
          xs={6}
        >
          <Box sx={{ mt: '10px', mb: '10px', textAlign: 'right' }}>
            <Typography fontSize={20}>
              {getPriceFormat(PurchaseReceiptDataMemo.netTotal, currencyCode)}
            </Typography>
          </Box>
        </Grid>
      </Grid>
      <Divider
        flexItem
        orientation="horizontal"
        sx={{ border: '1px dashed #E0E0E0' }}
      />
      <Box sx={{ height: '50px' }} />
    </div>
  );
});
